#!/usr/bin/env python3
"""Convert resume markdown to styled HTML, then print PDF via Chrome headless."""

from __future__ import annotations

import html
import re
import subprocess
import sys
from pathlib import Path

CHROME = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"

CSS = """
@page { size: A4; margin: 14mm 16mm; }
* { box-sizing: border-box; }
body {
  font-family: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
  font-size: 10.5pt;
  line-height: 1.45;
  color: #1a1a1a;
  max-width: 100%;
}
h1 {
  font-size: 20pt;
  text-align: center;
  margin: 0 0 10px;
  letter-spacing: 1px;
}
h2 {
  font-size: 12pt;
  margin: 14px 0 6px;
  padding-bottom: 3px;
  border-bottom: 1.5px solid #222;
}
h3 {
  font-size: 11pt;
  margin: 10px 0 4px;
  color: #111;
}
p { margin: 4px 0; }
ul { margin: 4px 0 6px 18px; padding: 0; }
li { margin: 2px 0; }
hr { border: none; border-top: 1px solid #ddd; margin: 8px 0; }
strong { font-weight: 600; }
table {
  width: 100%;
  border-collapse: collapse;
  margin: 6px 0 8px;
  font-size: 10pt;
}
td {
  border: 1px solid #ddd;
  padding: 4px 8px;
  vertical-align: top;
}
.meta-line { text-align: center; margin: 2px 0 8px; color: #333; }
.section-label { font-weight: 600; }
.tech-line { margin: 4px 0; }
.resp-list { margin-left: 18px; }
.sub-block { margin-left: 0; }
"""


def inline_format(text: str) -> str:
    text = html.escape(text)
    text = re.sub(r"\*\*(.+?)\*\*", r"<strong>\1</strong>", text)
    return text


def parse_table(lines: list[str]) -> str:
    rows = []
    for line in lines:
        if re.match(r"^\|\s*[-:| ]+\|\s*$", line):
            continue
        cells = [c.strip() for c in line.strip().strip("|").split("|")]
        rows.append(cells)
    if not rows:
        return ""
    out = ["<table>"]
    for row in rows:
        out.append("<tr>" + "".join(f"<td>{inline_format(c)}</td>" for c in row) + "</tr>")
    out.append("</table>")
    return "\n".join(out)


def md_to_html(md: str) -> str:
    lines = md.splitlines()
    body: list[str] = []
    i = 0
    while i < len(lines):
        line = lines[i]

        if line.strip() == "---":
            body.append("<hr/>")
            i += 1
            continue

        if line.startswith("# "):
            body.append(f"<h1>{inline_format(line[2:].strip())}</h1>")
            i += 1
            continue

        if line.startswith("## "):
            body.append(f"<h2>{inline_format(line[3:].strip())}</h2>")
            i += 1
            continue

        if line.startswith("### "):
            body.append(f"<h3>{inline_format(line[4:].strip())}</h3>")
            i += 1
            continue

        if line.startswith("|"):
            table_lines = []
            while i < len(lines) and lines[i].startswith("|"):
                table_lines.append(lines[i])
                i += 1
            body.append(parse_table(table_lines))
            continue

        if re.match(r"^\s*-\s+", line):
            body.append("<ul>")
            while i < len(lines) and re.match(r"^\s*-\s+", lines[i]):
                item = re.sub(r"^\s*-\s+", "", lines[i])
                if re.match(r"^\s{2,}-\s+", lines[i + 1] if i + 1 < len(lines) else ""):
                    # nested handled simply as same list
                    pass
                body.append(f"<li>{inline_format(item)}</li>")
                i += 1
            body.append("</ul>")
            continue

        if re.match(r"^\d+\.\s+", line.strip()):
            body.append("<ol class='resp-list'>")
            while i < len(lines) and re.match(r"^\d+\.\s+", lines[i].strip()):
                item = re.sub(r"^\d+\.\s+", "", lines[i].strip())
                body.append(f"<li>{inline_format(item)}</li>")
                i += 1
            body.append("</ol>")
            continue

        if line.strip().startswith("**") and line.strip().endswith("**") and line.count("**") == 2:
            label, _, rest = line.strip()[2:].partition("**")
            if rest.startswith("：") or rest.startswith(":"):
                body.append(f"<p class='section-label'><strong>{html.escape(label)}</strong>{inline_format(rest)}</p>")
            else:
                body.append(f"<p class='tech-line'>{inline_format(line.strip())}</p>")
            i += 1
            continue

        if line.strip():
            body.append(f"<p>{inline_format(line.strip())}</p>")
        i += 1

    return f"""<!DOCTYPE html>
<html lang=\"zh-CN\">
<head>
<meta charset=\"utf-8\"/>
<title>Zayn 个人简历</title>
<style>{CSS}</style>
</head>
<body>
{''.join(body)}
</body>
</html>
"""


def main() -> int:
    src = Path("/Users/mac/Desktop/CHcode/docs/Zayn_简历_流批一体融合版.md")
    html_path = Path("/Users/mac/Desktop/CHcode/docs/Zayn_简历_流批一体融合版.html")
    pdf_path = Path("/Users/mac/Downloads/Zayn_简历_流批一体融合版.pdf")

    md_text = src.read_text(encoding="utf-8")
    html_path.write_text(md_to_html(md_text), encoding="utf-8")

    cmd = [
        CHROME,
        "--headless=new",
        "--disable-gpu",
        "--no-pdf-header-footer",
        f"--print-to-pdf={pdf_path}",
        html_path.as_uri(),
    ]
    subprocess.run(cmd, check=True)
    print(f"PDF written: {pdf_path}")
    return 0


if __name__ == "__main__":
    sys.exit(main())

