HTML_OUT = Path("/Users/mac/Desktop/CHcode/docs/Zayn_简历_流批一体融合版.html")
PDF_OUT = Path("/Users/mac/Downloads/Zayn_简历_流批一体融合版.pdf")

CSS = """
