def fmt(text: str) -> str:
    text = html.escape(text.strip())
    return re.sub(r"\*\*(.+?)\*\*", r"<strong>\1</strong>", text)


def is_blank(line: str) -> bool:
    return not line.strip()


def is_hr(line: str) -> bool:
    return line.strip() == "---"


def ul_depth(line: str) -> int:
    m = re.match(r"^(\s*)-\s+", line)
    return len(m.group(1)) // 2 if m else -1


def parse_ul_block(lines: list[str], start: int) -> tuple[str, int]:
    parts: list[str] = []
    i = start
    base = ul_depth(lines[i])
    parts.append("<ul>")
    while i < len(lines):
        line = lines[i]
        if is_blank(line) or is_hr(line):
            break
        d = ul_depth(line)
        if d < 0:
            if line.startswith("## ") or line.startswith("### ") or re.match(r"^\d+\.\s+", line.strip()):
                break
            if line.strip().startswith("**") and line.strip().endswith("**") and line.count("**") == 2:
                break
            break
        if d > base:
            inner, i = parse_ul_block(lines, i)
            parts.append(inner)
            continue
        if d < base:
            break
        item = re.sub(r"^\s*-\s+", "", line)
        parts.append(f"<li>{fmt(item)}</li>")
        i += 1
    parts.append("</ul>")
    return "".join(parts), i


def parse_ol_block(lines: list[str], start: int, css_class: str = "arch-list") -> tuple[str, int]:
    parts: list[str] = [f'<ol class="{css_class}">']
    i = start
    while i < len(lines):
        line = lines[i]
        if is_blank(line) or is_hr(line):
            break
        m = re.match(r"^(\d+)\.\s+(.*)$", line.strip())
        if not m:
            break
        item_head = m.group(2)
        i += 1
        body_parts: list[str] = []
        sub_ul: list[str] = []

        while i < len(lines):
            nxt = lines[i]
            if is_blank(nxt):
                i += 1
                break
            if is_hr(nxt) or nxt.startswith("## ") or nxt.startswith("### "):
                break
            if re.match(r"^\d+\.\s+", nxt.strip()):
                break
            if nxt.strip().startswith("**") and nxt.count("**") == 2 and not nxt.strip().endswith("**"):
                break
            if nxt.strip().startswith("**") and nxt.strip().endswith("**") and nxt.count("**") == 2:
                break
            if ul_depth(nxt) >= 0:
                ul_html, i = parse_ul_block(lines, i)
                sub_ul.append(ul_html)
                continue
            if re.match(r"^\s{2,}\S", nxt) and ul_depth(nxt) < 0:
                body_parts.append(fmt(nxt.strip()))
                i += 1
                continue
            break

        inner = f'<span class="arch-body">{fmt(item_head)}</span>'
        if body_parts:
            inner += "".join(f"<div>{p}</div>" for p in body_parts)
        if sub_ul:
            inner += "".join(sub_ul)
        parts.append(f"<li>{inner}</li>")
    parts.append("</ol>")
    return "".join(parts), i


def parse_info_table(lines: list[str], start: int) -> tuple[str, int]:
    rows: list[list[str]] = []
    i = start
    while i < len(lines) and lines[i].startswith("|"):
        if not re.match(r"^\|\s*[-:| ]+\|\s*$", lines[i]):
            cells = [c.strip() for c in lines[i].strip().strip("|").split("|")]
            rows.append(cells)
        i += 1

    out = ['<table class="info-table"><tbody>']
    for row in rows:
        out.append("<tr>")
        for idx, cell in enumerate(row):
            if not cell:
                continue
            if cell.startswith("**") and cell.endswith("**"):
                out.append(f'<td class="label">{fmt(cell)}</td>')
            else:
                out.append(f'<td class="val">{fmt(cell)}</td>')
        out.append("</tr>")
    out.append("</tbody></table>")
    return "".join(out), i


def parse_skill_block(lines: list[str], start: int) -> tuple[str, int]:
    parts: list[str] = []
    i = start
    while i < len(lines):
        line = lines[i].strip()
        if not line:
            break
        if line.startswith("## "):
            break
        m = re.match(r"^\*\*(.+?)\*\*\s*$", line)
        if m:
            label = m.group(1)
            i += 1
            content = lines[i].strip() if i < len(lines) else ""
            i += 1
            parts.append(
                f'<div class="skill-row"><span class="label">{html.escape(label)}：</span>'
                f'<span class="content">{fmt(content)}</span></div>'
            )
            continue
        break
    return "".join(parts), i


def md_to_html(md: str) -> str:
    lines = md.splitlines()
    body: list[str] = []
    i = 0

    while i < len(lines):
        line = lines[i]

        if is_blank(line):
            i += 1
            continue

        if is_hr(line):
            i += 1
            continue

        if line.startswith("# "):
            body.append(f'<div class="doc-title">{fmt(line[2:])}</div>')
            i += 1
            continue

        if line.startswith("## "):
            body.append(f'<div class="section-title">{fmt(line[3:])}</div>')
            i += 1
            continue

        if line.startswith("### "):
            title = fmt(line[4:])
            if i > 0 and "项目经验" in md and body and "project-block" not in body[-1][-20:]:
                pass
            cls = "project-title" if "（" in line or "平台" in line or "系统" in line or "工具" in line else "job-title"
            if "项目经验" in "\n".join(lines[max(0, i - 30):i]):
                body.append(f'<div class="project-block"><div class="{cls}">{title}</div>')
            else:
                body.append(f'<div class="job-block"><div class="{cls}">{title}</div>')
            i += 1
            continue

        if line.startswith("|"):
            table_html, i = parse_info_table(lines, i)
            body.append(table_html)
            continue

        stripped = line.strip()

        if stripped.startswith("**") and stripped.endswith("**") and stripped.count("**") == 2:
            label = stripped[2:-2]
            if re.match(r"\d{4}/\d{2}\s*[–-]", label):
                body.append(f'<div class="date-line">{fmt(stripped)}</div>')
            elif label in {"项目简介", "技术架构", "技术实现", "责任描述"}:
                body.append(f'<div class="sub-title">{html.escape(label)}</div>')
            else:
                body.append(f'<div class="sub-title">{html.escape(label)}</div>')
            i += 1
            continue

        if "：" in stripped and stripped.startswith("**"):
            m = re.match(r"^\*\*(.+?)\*\*[：:](.*)$", stripped)
            if m:
                body.append(
                    f'<div class="tagline"><span class="label">{html.escape(m.group(1))}：</span>'
                    f'{fmt(m.group(2))}</div>'
                )
                i += 1
                continue

        if ul_depth(line) >= 0:
            ul_html, i = parse_ul_block(lines, i)
            body.append(ul_html)
            continue

        if re.match(r"^\d+\.\s+", stripped):
            ol_html, i = parse_ol_block(lines, i)
            body.append(ol_html)
            continue

        if line.startswith("## 技能特长") or (body and "技能特长" in body[-1]):
            pass

        # close open project/job blocks before new section
        if stripped.startswith("## "):
            pass

        # skill section rows handled when label-only above; plain paragraph otherwise
        body.append(f'<div class="p">{fmt(stripped)}</div>')
        i += 1

    # close dangling blocks
    html_text = "\n".join(body)
    html_text = html_text.replace('<div class="project-block">', '<div class="project-block">', 1)
    # append closing divs for project/job blocks - simpler: post-process
    open_projects = html_text.count('<div class="project-block">')
    open_jobs = html_text.count('<div class="job-block">')
    # Each gets closed before next same type or at skill section - rewrite approach

    return wrap_html(rebuild_with_closures(lines))


def rebuild_with_closures(lines: list[str]) -> str:
    """Second-pass structured builder for reliable block closing."""
    parts: list[str] = []
    i = 0
    in_project = False
    in_job = False
    in_skills = False

    def close_blocks():
        nonlocal in_project, in_job
        if in_project:
            parts.append("</div>")
            in_project = False
        if in_job:
            parts.append("</div>")
            in_job = False

    while i < len(lines):
        line = lines[i]
        if is_blank(line) or is_hr(line):
            i += 1
            continue

        if line.startswith("# "):
            parts.append(f'<div class="doc-title">{fmt(line[2:])}</div>')
            i += 1
            continue

        if line.startswith("## 技能特长"):
            close_blocks()
            in_skills = True
            parts.append(f'<div class="section-title">{fmt("技能特长")}</div>')
            i += 1
            continue

        if line.startswith("## "):
            close_blocks()
            in_skills = False
            parts.append(f'<div class="section-title">{fmt(line[3:])}</div>')
            i += 1
            continue

        if line.startswith("### "):
            close_blocks()
            title = fmt(line[4:])
            if i > 0 and any("## 项目经验" == l.strip() for l in lines[:i][::-1][:50]):
                parts.append(f'<div class="project-block"><div class="project-title">{title}</div>')
                in_project = True
            else:
                parts.append(f'<div class="job-block"><div class="job-title">{title}</div>')
                in_job = True
            i += 1
            continue

        if in_skills and line.strip().startswith("**") and line.strip().endswith("**"):
            label = line.strip()[2:-2]
            i += 1
            content = lines[i].strip() if i < len(lines) else ""
            i += 1
            parts.append(
                f'<div class="skill-row"><span class="label">{html.escape(label)}：</span>'
                f'<span class="content">{fmt(content)}</span></div>'
            )
            continue

        if line.startswith("|"):
            table_html, i = parse_info_table(lines, i)
            parts.append(table_html)
            continue

        stripped = line.strip()

        if stripped.startswith("**") and stripped.endswith("**") and stripped.count("**") == 2:
            label = stripped[2:-2]
            if re.match(r"\d{4}/\d{2}\s*[–-]", label):
                parts.append(f'<div class="date-line">{fmt(stripped)}</div>')
            else:
                parts.append(f'<div class="sub-title">{html.escape(label)}</div>')
            i += 1
            continue

        m = re.match(r"^\*\*(.+?)\*\*[：:](.*)$", stripped)
        if m:
            parts.append(
                f'<div class="tagline"><strong>{html.escape(m.group(1))}：</strong>{fmt(m.group(2))}</div>'
            )
            i += 1
            continue

        if ul_depth(line) >= 0:
            ul_html, i = parse_ul_block(lines, i)
            parts.append(ul_html)
            continue

        if re.match(r"^\d+\.\s+", stripped):
            ol_html, i = parse_ol_block(lines, i)
            parts.append(ol_html)
            continue

        # tech stack plain line after **技术实现**
        if parts and parts[-1].endswith("技术实现</div>"):
            parts.append(f'<div class="tech-stack">{fmt(stripped)}</div>')
        elif parts and "project-block" in parts[-1] and stripped and not stripped.startswith("<"):
            parts.append(f'<div class="p-intro">{fmt(stripped)}</div>')
        else:
            parts.append(f'<div class="p">{fmt(stripped)}</div>')
        i += 1

    close_blocks()
    return "\n".join(parts)


def wrap_html(body: str) -> str:
    return f"""<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="utf-8"/>
<meta name="viewport" content="width=device-width, initial-scale=1"/>
<title>Zayn 个人简历</title>
<style>{CSS}</style>
</head>
<body>
<div class="doc">
{body}
</div>
</body>
</html>
"""


def main() -> int:
    md_text = SRC.read_text(encoding="utf-8")
    html_content = wrap_html(rebuild_with_closures(md_text.splitlines()))
    HTML_OUT.write_text(html_content, encoding="utf-8")

    cmd = [
        CHROME,
        "--headless=new",
        "--disable-gpu",
        "--run-all-compositor-stages-before-draw",
        "--virtual-time-budget=10000",
        "--no-pdf-header-footer",
        f"--print-to-pdf={PDF_OUT}",
        HTML_OUT.as_uri(),
    ]
    subprocess.run(cmd, check=True, capture_output=True)
    print(f"HTML: {HTML_OUT}")
    print(f"PDF:  {PDF_OUT}")
    return 0


if __name__ == "__main__":
    sys.exit(main())

