def fmt(text: str) -> str:
    text = html.escape(text.strip())
    return re.sub(r"\*\*(.+?)\*\*", r"<strong>\1</strong>", text)


def is_blank(line: str) -> bool:
    return not line.strip()


def ul_match(line: str) -> re.Match[str] | None:
    return re.match(r"^(\s*)-\s+(.*)$", line)


def parse_ul(lines: list[str], i: int) -> tuple[str, int]:
    """Parse bullet list with proper nested <ul> inside parent <li>."""
    parts = ['<ul>']
    while i < len(lines):
        line = lines[i]
        if is_blank(line):
            break
        m = ul_match(line)
        if not m:
            break
        depth = len(m.group(1)) // 2
        if depth > 0:
            break
        text = m.group(2)
        i += 1
        nested = ""
        if i < len(lines) and ul_match(lines[i]) and len(ul_match(lines[i]).group(1)) // 2 > 0:
            nested, i = parse_nested_ul(lines, i)
        parts.append(f"<li>{fmt(text)}{nested}</li>")
    parts.append("</ul>")
    return "".join(parts), i


def parse_nested_ul(lines: list[str], i: int) -> tuple[str, int]:
    base = len(ul_match(lines[i]).group(1)) // 2
    parts = ['<ul class="nested">']
    while i < len(lines):
        m = ul_match(lines[i])
        if not m or is_blank(lines[i]):
            break
        depth = len(m.group(1)) // 2
        if depth < base:
            break
        if depth > base:
            inner, i = parse_nested_ul(lines, i)
            parts[-1] = parts[-1] + inner + "</li>"
            continue
        text = m.group(2)
        i += 1
        nested = ""
        if i < len(lines):
            nm = ul_match(lines[i])
            if nm and len(nm.group(1)) // 2 > depth:
                nested, i = parse_nested_ul(lines, i)
        parts.append(f"<li>{fmt(text)}{nested}</li>")
    parts.append("</ul>")
    return "".join(parts), i


def parse_ol(lines: list[str], i: int) -> tuple[str, int]:
    parts = ['<ol class="arch-list">']
    while i < len(lines):
        if is_blank(lines[i]):
            i += 1
            break
        m = re.match(r"^(\d+)\.\s+(.*)$", lines[i].strip())
        if not m:
            break
        head = m.group(2)
        i += 1
        body: list[str] = []
        nested = ""
        while i < len(lines):
            if is_blank(lines[i]):
                i += 1
                break
            if lines[i].startswith("## ") or lines[i].startswith("### "):
                break
            if re.match(r"^\d+\.\s+", lines[i].strip()):
                break
            if lines[i].strip().startswith("**") and lines[i].count("**") == 2:
                if lines[i].strip().endswith("**") and lines[i].strip() != f"**{lines[i].strip()[2:-2]}**":
                    pass
                st = lines[i].strip()
                if st in {"**项目简介**", "**技术架构**", "**技术实现**", "**责任描述**"} or (
                    st.startswith("**") and st.endswith("**") and "：" not in st and ":" not in st
                ):
                    break
            um = ul_match(lines[i])
            if um and len(um.group(1)) // 2 == 0:
                break
            if um and len(um.group(1)) // 2 > 0:
                nested, i = parse_nested_ul(lines, i)
                break
            if re.match(r"^\s{2,}\S", lines[i]) and not ul_match(lines[i]):
                body.append(fmt(lines[i].strip()))
                i += 1
                continue
            break
        inner = fmt(head)
        if body:
            inner += "".join(f"<div>{b}</div>" for b in body)
        if nested:
            inner += nested
        parts.append(f"<li>{inner}</li>")
    parts.append("</ol>")
    return "".join(parts), i


def parse_info_table(lines: list[str], i: int) -> tuple[str, int]:
    rows: list[list[str]] = []
    while i < len(lines) and lines[i].startswith("|"):
        if not re.match(r"^\|\s*[-:| ]+\|\s*$", lines[i]):
            rows.append([c.strip() for c in lines[i].strip().strip("|").split("|")])
        i += 1
    out = ['<table class="info-table"><tbody>']
    for row in rows:
        out.append("<tr>")
        for cell in row:
            if not cell:
                continue
            cls = "label" if cell.startswith("**") else "val"
            out.append(f'<td class="{cls}">{fmt(cell)}</td>')
        out.append("</tr>")
    out.append("</tbody></table>")
    return "".join(out), i


def build_html(lines: list[str]) -> str:
    parts: list[str] = []
    section = ""
    open_block: str | None = None

    def close_block():
        nonlocal open_block
        if open_block:
            parts.append("</div>")
            open_block = None

    i = 0
    while i < len(lines):
        line = lines[i]
        if is_blank(line) or line.strip() == "---":
            i += 1
            continue

        if line.startswith("# "):
            parts.append(f'<div class="doc-title">{fmt(line[2:])}</div>')
            i += 1
            continue

        if line.startswith("## "):
            close_block()
            title = line[3:].strip()
            if title == "技能特长":
                section = "skill"
            elif title == "项目经验":
                section = "project"
            elif title == "工作经验":
                section = "work"
            else:
                section = "other"
            parts.append(f'<div class="section-title">{fmt(title)}</div>')
            i += 1
            continue

        if line.startswith("### "):
            close_block()
            title = fmt(line[4:])
            if section == "project":
                parts.append(f'<div class="project-block"><div class="project-title">{title}</div>')
                open_block = "project"
            else:
                parts.append(f'<div class="job-block"><div class="job-title">{title}</div>')
                open_block = "job"
            i += 1
            continue

        if line.startswith("|"):
            tbl, i = parse_info_table(lines, i)
            parts.append(tbl)
            continue

        stripped = line.strip()

        if section == "skill" and stripped.startswith("**") and stripped.endswith("**"):
            label = stripped[2:-2]
            i += 1
            content = lines[i].strip() if i < len(lines) else ""
            i += 1
            parts.append(
                f'<div class="skill-row"><span class="label">{html.escape(label)}：</span>'
                f'<span class="content">{fmt(content)}</span></div>'
            )
            continue

        m = re.match(r"^\*\*(.+?)\*\*[：:]\s*(.*)$", stripped)
        if m:
            parts.append(
                f'<div class="tagline"><strong>{html.escape(m.group(1))}：</strong>{fmt(m.group(2))}</div>'
            )
            i += 1
            continue

        if stripped.startswith("**") and stripped.endswith("**") and stripped.count("**") == 2:
            label = stripped[2:-2]
            if re.match(r"\d{4}/\d{2}\s*[–-]", label):
                parts.append(f'<div class="date-line">{fmt(stripped)}</div>')
            else:
                parts.append(f'<div class="sub-title">{html.escape(label)}</div>')
            i += 1
            continue

        if ul_match(line) and len(ul_match(line).group(1)) == 0:
            ul_html, i = parse_ul(lines, i)
            parts.append(ul_html)
            continue

        if re.match(r"^\d+\.\s+", stripped):
            ol_html, i = parse_ol(lines, i)
            parts.append(ol_html)
            continue

        if parts and parts[-1].endswith("技术实现</div>"):
            parts.append(f'<div class="tech-stack">{fmt(stripped)}</div>')
        else:
            parts.append(f'<div class="p">{fmt(stripped)}</div>')
        i += 1

    close_block()
    return "\n".join(parts)


def main() -> int:
    lines = SRC.read_text(encoding="utf-8").splitlines()
    body = build_html(lines)
    html_doc = f"""<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="utf-8"/>
<title>Zayn 个人简历</title>
<style>{CSS}</style>
</head>
<body><div class="doc">
{body}
</div></body></html>"""
    HTML_OUT.write_text(html_doc, encoding="utf-8")

    subprocess.run(
        [
            CHROME,
            "--headless=new",
            "--disable-gpu",
            "--run-all-compositor-stages-before-draw",
            "--virtual-time-budget=10000",
            "--no-pdf-header-footer",
            f"--print-to-pdf={PDF_OUT}",
            HTML_OUT.as_uri(),
        ],
        check=True,
        capture_output=True,
    )
    print(f"PDF: {PDF_OUT}")
    return 0


if __name__ == "__main__":
    sys.exit(main())

