def fmt(text: str, allow_role_bold: bool = False) -> str:
    """Plain text by default; optional role-tag bold for responsibility lines."""
    text = text.strip()
    if allow_role_bold:
        for role in ROLE_PREFIXES:
            if text.startswith(f"**{role}**"):
                rest = text[len(f"**{role}**") :]
