                sep = "：" if "：" in text[: len(role) + 2] else ":"
                rest = text[len(role) + 1 :].lstrip()
                return f'<span class="role-tag">{html.escape(role)}：</span>{html.escape(rest)}'
    # strip any remaining markdown bold
    text = re.sub(r"\*\*(.+?)\*\*", r"\1", text)
    return html.escape(text)


